<script setup lang="ts">
import {reactive,ref,computed,onMounted} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {useCatalog} from '../stores/catalog'
import ApiOperations from '../components/ApiOperations.vue'
import {generateOpenApi,validateApi,specFilename} from '../services/openapi'
import {download} from '../utils/common'
import type {Api} from '../types'
const s=useCatalog(),route=useRoute(),router=useRouter(),editing=ref(false)
const blank=():Api=>({id:`api-${crypto.randomUUID()}`,name:'',version:'v1',backend:'',suffix:'',team:'',contact:'',vault:'',codeRepo:'',status:'beta',auth:'oauth',desc:'',ops:[['GET','/health','Service health']],origin:'created',consumers:0})
const form=reactive<Api>(blank()),justification=ref(''),showErrors=ref(false)
const errors=computed(()=>validateApi(form,s.apis))
const duplicateNames=computed(()=>s.apis.filter(a=>a.id!==form.id&&(a.backend===form.backend&&form.backend||a.name.toLowerCase()===form.name.toLowerCase()&&!!form.name)).slice(0,5))
const preview=computed(()=>generateOpenApi(form))
function save(){showErrors.value=true;if(errors.value.length)return;if(duplicateNames.value.length&&!justification.value.trim()){window.alert('Explain why an existing backend/API is insufficient before creating a duplicate.');return}const api=structuredClone({...form,specFile:`apis/${form.name.toLowerCase().replace(/[^a-z0-9]+/g,'-')}/${form.version}/openapi.yaml`});if(editing.value){s.updateApi(api);s.metrics.opsAdded++}else{s.addApi(api);if(duplicateNames.value.length)s.metrics.createdDespite++}router.push({path:'/docs',query:{id:api.id}})}
function useExisting(id:string){router.push({path:'/docs',query:{id}})}
onMounted(()=>{const id=String(route.query.extend||'');const existing=s.apis.find(a=>a.id===id);if(existing){Object.assign(form,structuredClone(existing));editing.value=true}})
</script>
<template><h1>{{editing?'Extend existing API':'Create a new API'}}</h1><p class="sub">Design your gateway contract, validate metadata and generate OpenAPI 3.0.3.</p><div class="stp"><span class="sp done"><i>1</i> Define</span><em/><span class="sp"><i>2</i> Validate</span><em/><span class="sp"><i>3</i> Export</span></div>
<div class="cg"><section class="card"><h2>API specification details</h2><div class="row"><div><label for="name">API name *</label><input id="name" v-model="form.name" placeholder="Customer Management API"/></div><div><label>Version</label><input v-model="form.version" placeholder="v1"/></div></div><label>Description</label><textarea v-model="form.desc" rows="3" placeholder="Describe this API and its business purpose"/><label>Backend URL *</label><input v-model="form.backend" placeholder="https://backend.example.com/api"/><label>Gateway suffix *</label><input v-model="form.suffix" placeholder="/customer/v1"/><div class="row"><div><label>Owning team *</label><input v-model="form.team" placeholder="Integration Platform"/></div><div><label>Contact email</label><input v-model="form.contact" type="email" placeholder="team@example.com"/></div></div><div class="row"><div><label>Lifecycle status</label><select v-model="form.status"><option value="active">Active</option><option value="beta">Beta</option><option value="deprecated">Deprecated</option></select></div><div><label>Authentication</label><select v-model="form.auth"><option value="oauth">OAuth 2.0 bearer</option><option value="key">Subscription key</option></select></div></div><label>Code repository</label><input v-model="form.codeRepo" placeholder="https://github.com/org/repo"/><label>Key Vault named value</label><input v-model="form.vault" placeholder="kv-prod/api-secret"/><hr style="border:0;border-top:1px solid var(--bd);margin:20px 0"/><h2>Operations</h2><ApiOperations v-model="form.ops"/><div v-if="duplicateNames.length" class="note warn mt"><b>Potential duplicate detected</b><p>These existing APIs match the name or backend. Review reuse before creating another API.</p><div v-for="a in duplicateNames" :key="a.id" class="ur"><span>{{a.name}} — {{a.backend}}</span><button class="lnk" @click="useExisting(a.id)">View</button></div><label>Why is a new API required?</label><textarea v-model="justification" rows="2" placeholder="Document missing functionality / a governance exception"/></div><div v-if="showErrors&&errors.length" class="err"><b>Resolve these validation issues:</b><ul><li v-for="(e,i) in errors" :key="i">{{e}}</li></ul></div><div class="actions"><button class="btn" @click="save">{{editing?'Save changes + simulate PR':'Create API + simulate PR'}}</button><button class="btn ghost" @click="download(specFilename(form),preview,'application/yaml')">Download draft YAML</button></div><p class="small mu">Saving updates the local catalog and creates a <b>simulated</b> Git pull request, not a real remote repository change.</p></section>
<div class="cg-r"><div class="card live"><div class="toolbar"><h2 style="margin:0">Live OpenAPI preview</h2><span class="ver">3.0.3</span></div><pre>{{preview}}</pre></div></div></div></template>
